import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.CodeBuilderSource{Operation: packet.CodeBuilderOperationReset,
# Category: packet.CodeBuilderCategoryInstantiation, CodeStatus: packet.CodeBuilderStatusSucceeded}
RESET = bytes.fromhex("030205")

# generated by gophertunnel b8bd735:
# &packet.CodeBuilderSource{Operation: packet.CodeBuilderOperationNone,
# Category: packet.CodeBuilderCategoryNone, CodeStatus: packet.CodeBuilderStatusNone}
ALL_NONE = bytes.fromhex("000000")

# generated by gophertunnel b8bd735:
# &packet.CodeBuilderSource{Operation: 200, Category: packet.CodeBuilderCategoryStatus,
# CodeStatus: packet.CodeBuilderStatusInProgress}
OPERATION_200 = bytes.fromhex("c80102")

GOLDENS = [
    pytest.param(
        v2225.CodeBuilderSourcePacket(
            operation=v2225.Operation.RESET,
            category=v2225.Category.INSTANTIATION,
            code_status=v2225.CodeStatus.SUCCEEDED,
        ),
        RESET,
        id="reset",
    ),
    pytest.param(
        v2225.CodeBuilderSourcePacket(
            operation=v2225.Operation.NONE, category=v2225.Category.NONE, code_status=v2225.CodeStatus.NONE
        ),
        ALL_NONE,
        id="all-none",
    ),
    pytest.param(
        v2225.CodeBuilderSourcePacket(
            operation=200, category=v2225.Category.CODE_STATUS, code_status=v2225.CodeStatus.IN_PROGRESS
        ),
        OPERATION_200,
        id="operation-above-127",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_code_builder_source_is_packet_178(version):
    assert version.PACKETS[178] is version.CodeBuilderSourcePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_code_builder_source_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_code_builder_source_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_code_builder_source_rejects_a_body_short_of_three_bytes():
    with pytest.raises(ValueError, match="at byte"):
        v2225.CodeBuilderSourcePacket.from_bytes(OPERATION_200[:2])
